  "Elements in": { es: "Elementos en", ar: "العناصر في", zh: "所含元素：", sw: "Elementi katika", sv: "Grundämnen i" },
  "What is the chemical symbol for": { es: "¿Cuál es el símbolo químico de", ar: "ما الرمز الكيميائي لعنصر", zh: "以下元素的化学符号是什么：", sw: "Alama ya kikemia ya", sv: "Vilken är den kemiska beteckningen för" },
  "(from its old or Latin name)": { es: "(de su nombre antiguo o latino)", ar: "(من اسمه القديم أو اللاتيني)", zh: "（来自它的旧名或拉丁名）", sw: "(kutoka jina lake la zamani au la Kilatini)", sv: "(från dess gamla eller latinska namn)" },
  "Which element has the symbol": { es: "¿Qué elemento tiene el símbolo", ar: "أي عنصر رمزه", zh: "哪种元素的符号是", sw: "Ni elementi gani yenye alama", sv: "Vilket grundämne har beteckningen" },
  "Which element has atomic number": { es: "¿Qué elemento tiene el número atómico", ar: "أي عنصر عدده الذري", zh: "哪种元素的原子序数是", sw: "Ni elementi gani yenye namba ya atomiki", sv: "Vilket grundämne har atomnummer" },
  "Which family does": { es: "¿A qué familia pertenece", ar: "إلى أي عائلة ينتمي", zh: "以下元素属于哪个类别：", sw: "Ni familia gani inayojumuisha", sv: "Vilken familj tillhör" },
  "Research only.": { es: "Solo para investigación.", ar: "للأبحاث فقط.", zh: "仅用于研究。", sw: "Kwa utafiti tu.", sv: "Endast för forskning." },
  "Which element is this? Used for: “": { es: "¿Qué elemento es? Se usa para: “", ar: "ما هذا العنصر؟ يُستخدم في: “", zh: "这是哪种元素？用途：“", sw: "Hii ni elementi gani? Hutumika kwa: “", sv: "Vilket grundämne är det här? Används till: “" },
  "What is the common name of": { es: "¿Cuál es el nombre común de", ar: "ما الاسم الشائع لـ", zh: "以下物质的俗名是什么：", sw: "Jina la kawaida la", sv: "Vad är det vardagliga namnet på" },
  "What is the chemical formula of": { es: "¿Cuál es la fórmula química de", ar: "ما الصيغة الكيميائية لـ", zh: "以下物质的化学式是什么：", sw: "Fomula ya kikemia ya", sv: "Vilken är den kemiska formeln för" },
  "Which element is a key ingredient of": { es: "¿Qué elemento es un ingrediente clave de", ar: "أي عنصر يُعدّ مكوّنًا أساسيًا في", zh: "以下哪种元素是这种材料的关键成分：", sw: "Ni elementi gani ni kiungo muhimu cha", sv: "Vilket grundämne är en viktig beståndsdel i" },
  "Explore at least 3 elements first, or choose another topic.": { es: "Explora primero al menos 3 elementos o elige otro tema.", ar: "استكشف 3 عناصر على الأقل أولًا، أو اختر موضوعًا آخر.", zh: "请先浏览至少 3 种元素，或选择其他主题。", sw: "Chunguza angalau elementi 3 kwanza, au chagua mada nyingine.", sv: "Utforska minst 3 grundämnen först, eller välj ett annat ämne." },
  "Tick at least one question type.": { es: "Marca al menos un tipo de pregunta.", ar: "اختر نوعًا واحدًا على الأقل من الأسئلة.", zh: "请至少勾选一种题型。", sw: "Weka alama kwenye angalau aina moja ya swali.", sv: "Kryssa i minst en frågetyp." },
  "No questions match — tick more question types.": { es: "Ninguna pregunta coincide: marca más tipos de pregunta.", ar: "لا أسئلة مطابقة — اختر أنواع أسئلة أكثر.", zh: "没有匹配的题目——请勾选更多题型。", sw: "Hakuna maswali yanayolingana — weka alama kwenye aina zaidi za maswali.", sv: "Inga frågor matchar — kryssa i fler frågetyper." },
  "The answer is": { es: "La respuesta es", ar: "الإجابة هي", zh: "答案是", sw: "Jibu ni", sv: "Svaret är" },
  "Nobel chemist 🏅": { es: "Químico de Nobel 🏅", ar: "كيميائي حائز نوبل 🏅", zh: "诺贝尔化学家 🏅", sw: "Mwanakemia wa Nobel 🏅", sv: "Nobelpristagare i kemi 🏅" },
  "Lab scientist 🧪": { es: "Científico de laboratorio 🧪", ar: "عالم مختبر 🧪", zh: "实验室科学家 🧪", sw: "Mwanasayansi wa maabara 🧪", sv: "Laboratorieforskare 🧪" },
  "Chemistry student 📘": { es: "Estudiante de química 📘", ar: "طالب كيمياء 📘", zh: "化学学生 📘", sw: "Mwanafunzi wa kemia 📘", sv: "Kemistudent 📘" },
  "Lab assistant 🥽": { es: "Ayudante de laboratorio 🥽", ar: "مساعد مختبر 🥽", zh: "实验室助手 🥽", sw: "Msaidizi wa maabara 🥽", sv: "Laboratorieassistent 🥽" },
